import { useEffect, useId, useRef, useState } from 'react';
import { activateVendor } from '../../lib/vendor-approvals';
export default function VendorActivationModal({ state, onClose, onSaved }) {
  const ref = useRef(null), pending = useRef(false), prefix = useId();const [confirmed, setConfirmed] = useState(false), [busy, setBusy] = useState(false), [error, setError] = useState('');
  useEffect(() => { const d = ref.current; d.showModal(); return () => d.close(); }, []);
  const submit = async (e) => { e.preventDefault(); if (pending.current || !confirmed) return; pending.current = true; setBusy(true); setError(''); try { await activateVendor(state); onSaved(); } catch (err) { setError(err.message); } finally { pending.current = false; setBusy(false); } };
  const matches = state.basis.master_matches;
  return <dialog ref={ref} aria-labelledby={prefix + 'title'} onCancel={(e) => { e.preventDefault(); if (!busy) onClose(); }} className="m-auto w-[calc(100%-2rem)] max-w-lg max-h-[90vh] overflow-y-auto rounded-xl border border-white/10 bg-ink-900 text-white p-5 backdrop:bg-black/70"><form onSubmit={submit} className="space-y-4"><h2 id={prefix + 'title'} className="text-lg font-semibold">Aktifkan Vendor Operasional</h2><p className="text-sm">{state.business_name} · keputusan {state.latest_decision.decision_code}</p><p className="text-sm text-ink-400">{matches.length ? `Gunakan master ${matches[0].vendor_code}. Profil master dan relasi aset yang sudah ada dipertahankan.` : 'Buat satu master vendor baru dari profil, kontak dan alamat utama kandidat, lalu hubungkan untuk operasional.'}</p>
    {state.latest_decision.override_reason && <p className="card p-3 text-sm text-warning-400 whitespace-pre-wrap">Pengecualian: {state.latest_decision.override_reason}</p>}
    <label className="text-sm flex items-start gap-2"><input type="checkbox" required disabled={busy} checked={confirmed} onChange={(e) => setConfirmed(e.target.checked)} />Saya menyetujui aktivasi eksplisit vendor ini.</label>{error && <p role="alert" className="text-sm text-danger-400">{error}</p>}<div className="flex flex-wrap justify-end gap-2"><button type="button" className="btn-secondary" disabled={busy} onClick={onClose}>Batal</button><button className="btn-primary" disabled={busy || !confirmed}>{busy ? 'Mengaktifkan…' : 'Aktifkan Vendor'}</button></div></form></dialog>;
}
